onClick:
{{
  Insert_BL.run()
    .then((res) => {
      // 1. Vérification de l'identifiant retourné par Supabase
      if (!res || !res[0]) return Promise.reject("Aucun ID retourné");
      const newId = res[0].ID_BL || res[0].id_bl;
      if (!newId) return Promise.reject("Identifiant introuvable");

      // 2. Fermeture de la modale
      closeModal('modal_add_bon_de_livraison');

      // 3. Nettoyage des champs de saisie pour la prochaine fois
      resetWidget('sel_client', true);
      resetWidget('inp_new_notes', true);

      // 4. Message de succès
      showAlert('Bon de livraison créé !', 'success');

      // 5. Redirection immédiate vers la page "Détail Bon de Livraison" avec le nouvel ID
      navigateTo('Détail Bon de Livraison', { id: newId });
    })
    .catch((err) => {
      showAlert('Erreur lors de la création : ' + err, 'error');
    });
}}
